package org.tpmnigeria.tpm.data.local

import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey
import org.tpmnigeria.tpm.domain.model.AppNotification
import org.tpmnigeria.tpm.domain.model.UserRole

@Entity(
    tableName = "notifications",
    indices = [Index(value = ["remoteId"], unique = true)],
)
data class NotificationEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    /** Null for notifications generated by this device's own actions; set for ones pulled from
     *  the `notifications` table (e.g. a TPM Supervisor assigning a DRI from the web app) — lets
     *  repeated pulls insert-or-ignore instead of duplicating rows. See AppRepository.upsertRemoteNotifications. */
    val remoteId: String? = null,
    val role: UserRole,
    val issueId: String,
    val title: String,
    val body: String,
    val timestampMillis: Long,
    val unread: Boolean,
)

fun NotificationEntity.toDomain(): AppNotification = AppNotification(
    id = id, role = role, issueId = issueId, title = title, body = body,
    timestampMillis = timestampMillis, unread = unread,
)
